package com.appdimens.dynamic.custom

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
import kotlin.math.abs
import kotlin.math.max

/**
 * Runs `custom-strategy-fixture.json` — the same file every AppDimens platform tests
 * against (generated by this reference engine). Keeps the Kotlin engine from drifting.
 */
class CrossPlatformFixtureTest {

    @Suppress("UNCHECKED_CAST")
    @Test
    fun fixture_matchesReferenceEngine() {
        val text = javaClass.classLoader!!.getResource("custom-strategy-fixture.json")!!.readText()
        val root = MiniJson(text).parse() as Map<String, Any?>
        val tolerance = (root["tolerance"] as Number).toFloat()
        val documentJson = text.substring(text.indexOf("\"document\":") + "\"document\":".length, text.indexOf(",\n  \"screens\""))
        val strategies = ScalingStrategyJson.decode(documentJson).strategies
        val screens = (root["screens"] as Map<String, Map<String, Any?>>).mapValues { (_, s) ->
            ScreenSnapshot(
                widthDp = (s["width"] as Number).toFloat(),
                heightDp = (s["height"] as Number).toFloat(),
                smallestWidthDp = (s["smallestWidth"] as Number).toFloat(),
                density = (s["density"] as Number).toFloat(),
                fontScale = (s["fontScale"] as Number).toFloat(),
                isLandscape = s["landscape"] as Boolean,
                isMultiWindow = s["multiWindow"] as Boolean,
                device = DeviceClass.fromJson(s["device"] as String),
            )
        }
        val cases = root["cases"] as List<Map<String, Any?>>
        assertTrue(cases.isNotEmpty())
        for (c in cases) {
            val strategy = strategies.getValue(c["strategy"] as String)
            val resolved = strategy.resolve(screens.getValue(c["screen"] as String))
            val base = (c["base"] as Number).toFloat()
            val label = "${c["strategy"]}@${c["screen"]}×$base"
            close(label, (c["factor"] as Number).toFloat(), resolved.factor, tolerance)
            close(label, (c["dp"] as Number).toFloat(), resolved.scale(base), tolerance)
            close(label, (c["spDp"] as Number).toFloat(), resolved.scaleSpDp(base), tolerance)
            assertEquals(label, c["rules"], resolved.appliedRules)
        }
    }

    private fun close(label: String, expected: Float, actual: Float, tolerance: Float) {
        assertTrue("$label expected $expected got $actual", abs(expected - actual) <= tolerance * max(1f, abs(expected)))
    }
}
